function audio(){if(!soundEnabled)return null;if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioBus=audioCtx.createDynamicsCompressor();audioBus.threshold.value=-16;audioBus.ratio.value=5;const output=audioCtx.createGain();output.gain.value=.75*(typeof volumeLevel==='function'?volumeLevel('sfx'):1);sfxOutput=output;audioBus.connect(output);output.connect(audioCtx.destination);if(audioCtx.createConvolver){audioReverb=audioCtx.createConvolver();const impulse=audioCtx.createBuffer(2,Math.floor(audioCtx.sampleRate*.85),audioCtx.sampleRate);for(let channel=0;channel<2;channel++){const data=impulse.getChannelData(channel);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/data.length*7)*.4}audioReverb.buffer=impulse;const wet=audioCtx.createGain();wet.gain.value=.13;audioReverb.connect(wet);wet.connect(audioBus)}engineGain=audioCtx.createGain();engineGain.gain.value=0;engineOsc=audioCtx.createOscillator();engineOsc.type='triangle';engineOsc.frequency.value=45;engineOsc.connect(engineGain);engineGain.connect(audioBus);engineOsc.start();initEngineLayers();initBarrierPlasma()}if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function tone(freq,duration=.08,type='sine',volume=.035,slide=0,delay=0){const a=audio();if(!a)return;const o=a.createOscillator(),g=a.createGain(),now=a.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),now+duration);g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(volume,now+.004);g.gain.exponentialRampToValueAtTime(.0001,now+duration);const filter=a.createBiquadFilter();filter.type='lowpass';filter.frequency.value=Math.min(6500,freq*3);o.connect(filter);filter.connect(g);routeSound(g);o.start(now);o.stop(now+duration)}
function noise(duration=.25,volume=.035,frequency=1000,delay=0){const a=audio();if(!a)return;if(!noiseBuffer){noiseBuffer=a.createBuffer(1,a.sampleRate*2,a.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1}const source=a.createBufferSource(),filter=a.createBiquadFilter(),gain=a.createGain(),now=a.currentTime+delay;source.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.setValueAtTime(frequency,now);filter.frequency.exponentialRampToValueAtTime(80,now+duration);gain.gain.setValueAtTime(.0001,now);gain.gain.linearRampToValueAtTime(volume,now+.006);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);source.connect(filter);filter.connect(gain);routeSound(gain);source.start(now,Math.random()*.8);source.stop(now+duration)}
function sfx(name,power=1){if(!soundEnabled)return;if(name==='ui'){tone(640,.06,'sine',.018,960)}if(name==='shoot'){const pitch=.96+Math.random()*.08;tone(1700*pitch,.14,'sawtooth',.014,260);tone(920*pitch,.11,'sine',.032,145);tone(145,.09,'triangle',.018,65);noise(.035,.009,5400)}if(name==='hit'){noise(.12,.05,3200);noise(.32,.03,650);tone(105,.3,'triangle',.04,38)}if(name==='shield'){tone(260,.28,'sine',.04,720);tone(520,.18,'triangle',.015,1040)}if(name==='boost'){noise(.65,.035,1600);tone(55,.7,'triangle',.045,180)}if(name==='boom'){const pitch=.86+Math.random()*.24,weight=Math.min(1.5,Math.sqrt(power));noise(.075,.045*weight,6800);noise(.5,.07*weight,1900,.015);noise(1.15,.037*weight,480,.08);tone(78*pitch,1.05,'sine',.07*weight,23);tone(145*pitch,.28,'triangle',.022,42,.025);for(let i=0;i<3;i++)noise(.065+Math.random()*.07,.013*weight,2400+Math.random()*2600,.09+i*.075)}if(name==='warp'){noise(2.4,.06,5500);tone(45,1.8,'sawtooth',.025,1000);tone(90,2.4,'sine',.035,1500)}if(name==='missile')missileLaunchSound();if(name==='shipExplode')shipExplosionSound();if(name==='lock'){tone(880,.12,'sine',.025,1320);tone(1320,.24,'sine',.018,1760)}if(name==='dissolve'){noise(.15,.018,6500);tone(1600,.1,'sine',.012,500)}if(name==='orbit'){noise(1.1,.03,1800);tone(196,1.7,'sine',.035);tone(246.94,1.9,'sine',.025);tone(293.66,2.1,'sine',.025)}}
function initEngineLayers(){const a=audioCtx;engineSub=a.createOscillator();engineSub.type='sine';engineSub.frequency.value=30;const low=a.createGain();low.gain.value=.7;engineSub.connect(low);low.connect(engineGain);engineSub.start();engineHarmonic=a.createOscillator();engineHarmonic.type='triangle';engineHarmonic.frequency.value=90;const harmonic=a.createGain();harmonic.gain.value=.16;engineHarmonic.connect(harmonic);harmonic.connect(engineGain);engineHarmonic.start();const buffer=a.createBuffer(1,a.sampleRate*2,a.sampleRate),data=buffer.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){brown=(brown+(Math.random()*2-1)*.025)/1.025;data[i]=brown*4}const airflow=a.createBufferSource();airflow.buffer=buffer;airflow.loop=true;engineFilter=a.createBiquadFilter();engineFilter.type='lowpass';engineFilter.frequency.value=220;engineNoiseGain=a.createGain();engineNoiseGain.gain.value=0;airflow.connect(engineFilter);engineFilter.connect(engineNoiseGain);engineNoiseGain.connect(audioBus);airflow.start()}
function updateEngineSound(){if(!audioCtx||!engineGain)return;const active=soundEnabled&&!paused&&state==='play'&&player&&arrivalRemaining<=0,thrust=active?Math.max(Math.abs(player.forward),Math.abs(player.strafe)):0,boost=active&&player.boostState==='active',now=audioCtx.currentTime,load=boost?1.7:thrust;engineGain.gain.setTargetAtTime(active?.009+load*.021:0,now,.16);engineOsc.frequency.setTargetAtTime(44+load*37,now,.2);if(engineSub)engineSub.frequency.setTargetAtTime(28+load*15,now,.23);if(engineHarmonic)engineHarmonic.frequency.setTargetAtTime(88+load*76,now,.18);if(engineNoiseGain)engineNoiseGain.gain.setTargetAtTime(active?.009+load*.048:0,now,.16);if(engineFilter)engineFilter.frequency.setTargetAtTime(160+load*650,now,.2);const barrier=active&&player.barrier&&player.shield>0,pulse=barrier?(player.shieldPulse||0)/.55:0;if(plasmaGain)plasmaGain.gain.setTargetAtTime(barrier?.026+pulse*.025:0,now,.045);if(plasmaTone)plasmaTone.frequency.setTargetAtTime(172+pulse*85,now,.07);if(plasmaFilter)plasmaFilter.frequency.setTargetAtTime(780+pulse*900,now,.06)}
