function startGame(arriving=false){orbitTime=0;show('orbitCaption',false);arrivalRemaining=arriving?ARRIVAL_SECONDS:0;show('meteorAlert',false);document.body.classList.add('playing');const p=planets[selected];state='play';paused=false;missionTime=0;capture=0;pickups=[];missile=null;wingMissiles=[];lockTarget=null;lockProgress=0;reinforcementStage=0;beltWarned=false;fragments=[];shockwaves=[];shipDebris=[];deathTimer=0;deathFlash=0;deathBlasts=0;meteor=null;meteorTimer=12+Math.random()*8;shower=[];showerTimer=2;fleetWarned=false;showerWarned=false;approachAngle=Math.random()*Math.PI*2;keys={};mouse.down=false;mouse.right=false;mouse.turn=0;gameStart=performance.now();kills=0;player={x:0,y:0,vx:0,vy:0,r:13,angle:0,turnRemaining:0,stun:0,spin:0,health:100,shield:100,barrier:false,fire:0,inv:0,forward:0,strafe:0,boost:100,boostState:'ready',shieldDelay:0,shieldLock:false,shieldPulse:0};const AD=p.distance/18,ax=Math.cos(approachAngle),ay=Math.sin(approachAngle),P=(t,o)=>({x:t*ax-o*ay,y:t*ay+o*ax});player.angle=approachAngle;world={x:AD*ax,y:AD*ay,dist:AD,r:430+p.difficulty*18,p};bullets=[];enemies=[];rocks=[];wrecks=[];monsters=[];particles=[];makeScenery();makeOrbitalBelt();for(let i=0;i<6+p.difficulty*3;i++){const q=P(700+Math.random()*(AD-900),(Math.random()-.5)*1200);spawnEnemy(q.x,q.y)}for(let i=0;i<10+p.difficulty*4;i++){const r=18+Math.random()*45;rocks.push({rock:true,...P(500+Math.random()*(AD-600),(Math.random()-.5)*2400),r,vx:(Math.random()-.5)*12,vy:(Math.random()-.5)*12,rot:Math.random()*6,spin:(Math.random()-.5)*.3,hp:Math.max(2,Math.ceil(r/17)),hit:0})}for(let i=0;i<p.difficulty;i++){const r=100+Math.random()*90;wrecks.push({...P(1100+Math.random()*(AD-1700),(Math.random()-.5)*1600),r,rot:Math.random()*6,hp:Math.ceil(r/22),hit:0})}if(p.difficulty>=4)for(let i=0;i<p.difficulty-3;i++)monsters.push({...P(1800+Math.random()*(AD-2300),(Math.random()-.5)*1500),r:90+Math.random()*30,hp:18+p.difficulty*6,t:Math.random()*10,hit:0});$('hudPlanet').textContent=p.name;show('hud');$('mapScreen').classList.remove('active');status('USCITA DALL’IPERSPAZIO',1800);spawnGuardFleet();updateHud(Math.hypot(world.x,world.y));updateMissileHud();if(typeof ecoStartPhase==='function')ecoStartPhase(1)}
function spawnEnemy(x,y,enterFromEdge=true){const difficulty=planets[selected].difficulty,type=difficulty>=3&&enemies.length%3===2?'sniper':enemies.length%2?'flanker':'chaser',hp=type==='sniper'?5:3+Math.floor(difficulty/2);const safe=enemySpawnPosition(x,y??(Math.random()-.5)*1200,type==='sniper'?22:18,enterFromEdge);const arrivalAngle=Math.atan2(player.y-safe.y,player.x-safe.x);enemies.push({x:safe.x,y:safe.y,vx:enterFromEdge?Math.cos(arrivalAngle)*95:0,vy:enterFromEdge?Math.sin(arrivalAngle)*95:0,alerted:enterFromEdge,r:type==='sniper'?22:18,hp,maxHp:hp,type,fire:1.2+Math.random(),angle:0,hit:0,phase:Math.random()*6.28})}
function updateEnemies(dt){enemies.forEach(e=>{if(e.hp<=0)return;const dx=player.x-e.x,dy=player.y-e.y,d=Math.max(1,Math.hypot(dx,dy));e.angle=Math.atan2(dy,dx);e.phase+=dt;if(d<950)e.alerted=true;if(!e.alerted&&e.guard)guardPatrol(e,dt);if(e.alerted){const range=e.type==='sniper'?460:260,approach=d>range?1:d<range-70?-1:0,side=e.type==='flanker'?Math.sin(e.phase*.7)>=0?1:-1:0,speed=e.type==='flanker'?168:e.type==='sniper'?88:125;const tx=(dx/d*approach-dy/d*side*.85)*speed,ty=(dy/d*approach+dx/d*side*.85)*speed;const safe=avoidEnemyObstacles(e,tx,ty);e.vx+=(safe.x-e.vx)*Math.min(1,dt*4);e.vy+=(safe.y-e.vy)*Math.min(1,dt*4);e.fire-=dt;if(e.fire<=0&&d<720){enemyShoot(e);e.fire=(e.type==='sniper'?2.05:1.5)+Math.random()*.6}}e.prevX=e.x;e.prevY=e.y;e.x+=e.vx*dt;e.y+=e.vy*dt;collide(e,e.r,22,2,dt,'#ff5a3d')})}
function dropSupply(entity){const roll=Math.random();if(roll<SHIELD_DROP_CHANCE)dropShieldPill(entity.x,entity.y);else if(roll<.12)pickups.push({x:entity.x,y:entity.y,kind:player.health<70?'repair':'energy',life:24,r:12})}
function dropShieldPill(x,y){pickups.push({x,y,kind:'shield',life:35,r:12})}
function updateSupplies(dt){pickups.forEach(p=>{p.life-=dt;const dx=player.x-p.x,dy=player.y-p.y,d=Math.hypot(dx,dy);if(d<150&&d>1){p.x+=dx/d*220*dt;p.y+=dy/d*220*dt}if(d<player.r+p.r){p.life=0;if(p.kind==='shield'){player.shield=Math.min(100,player.shield+35);if(player.shield>=25)player.shieldLock=false;status('CAPSULA BARRIERA · +35%');sfx('shield')}else if(p.kind==='repair'){player.health=Math.min(100,player.health+22);status('RIPARAZIONE SCAFO +22%')}else{player.shield=Math.min(100,player.shield+30);player.boost=Math.min(100,player.boost+25);if(player.boost===100)player.boostState='ready';status('ENERGIA RECUPERATA')}sfx('ui')}});pickups=pickups.filter(p=>p.life>0)}
