function updateMouseSteering(dt){mouse.turn=0;player.turnRemaining=0;const dx=mouse.x-W/2,dy=mouse.y-H/2;if(dx*dx+dy*dy<64)return;const target=Math.atan2(dy,dx),diff=Math.atan2(Math.sin(target-player.angle),Math.cos(target-player.angle));player.angle+=diff*(-Math.expm1(-AIM_RESPONSE*dt));player.angle=Math.atan2(Math.sin(player.angle),Math.cos(player.angle))}
function requestFlightMouse(){placeCrosshair()}
function releaseFlightMouse(){if(document.pointerLockElement===canvas&&document.exitPointerLock)document.exitPointerLock()}
document.addEventListener('pointerlockchange',()=>{mouse.turn=0;if(player)player.turnRemaining=0;if(!document.pointerLockElement&&state==='play'&&!paused)togglePause()});

function nearestVisibleEnemy(){let nearest=null,best=Infinity;for(const e of enemies){if(e.hp<=0||Math.abs(e.x-player.x)>W/2+e.r||Math.abs(e.y-player.y)>H/2+e.r)continue;const d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<best){nearest=e;best=d}}return nearest}
function targetVisible(e){return !!e&&e.hp>0&&enemies.includes(e)&&Math.abs(e.x-player.x)<=W/2+e.r&&Math.abs(e.y-player.y)<=H/2+e.r}
function updateTargetLock(dt){const candidate=targetVisible(lockTarget)?lockTarget:nearestVisibleEnemy();if(candidate!==lockTarget){if(lockTarget)lockTarget.lockSoundPlayed=false;lockTarget=candidate;lockProgress=0}if(lockTarget)lockProgress=Math.min(1,lockProgress+dt/LOCK_SECONDS);else lockProgress=0;if(lockProgress>=1&&!lockTarget.lockSoundPlayed){sfx('lock');lockTarget.lockSoundPlayed=true}updateMissileHud()}
function updateMissileHud(){$('missileStatus').textContent=missile||wingMissiles.length?(wingMissiles.length?'MISSILI IN VOLO':'MISSILE IN VOLO'):lockTarget&&lockProgress>=1?'BERSAGLIO AGGANCIATO · CLIC ROTELLA':lockTarget?'AGGANCIO '+Math.floor(lockProgress*100)+'% · CLIC ROTELLA: TIRO DIRITTO':'MISSILE PRONTO · CLIC ROTELLA: TIRO DIRITTO';$('missileStatus').classList.toggle('locked',!!lockTarget&&lockProgress>=1)}
function launchMissile(){if(state!=='play'||paused||arrivalRemaining>0||player.stun>0||missile||wingMissiles.length)return;let count=1+upg('salvo');while(count>0&&!canPay('missile',count))count--;if(!count){status('CREDITI INSUFFICIENTI PER IL MISSILE',1400);tone(180,.1,'square',.015);return}pay('missile',count);const target=targetVisible(lockTarget)&&lockProgress>=1?lockTarget:null,a=player.angle;missile={x:player.x+Math.cos(a)*34,y:player.y+Math.sin(a)*34,angle:a,speed:340,life:7,target,r:5};const offsets=count===2?[-1,1]:count===3?[-1,1]:[];wingMissiles=offsets.slice(0,count-1).map(side=>{const wa=a+side*.16,px=-Math.sin(a)*side*16,py=Math.cos(a)*side*16;return{x:player.x+Math.cos(a)*26+px,y:player.y+Math.sin(a)*26+py,angle:wa,speed:330,life:7,target,r:5}});sfx('missile');status((count>1?count+' MISSILI ':'')+(target?(count>1?'AUTOGUIDATI LANCIATI':'MISSILE AUTOGUIDATO LANCIATO'):(count>1?'LANCIATI · ROTTA DIRITTA':'MISSILE LANCIATO · ROTTA DIRITTA')));updateMissileHud()}
// Swept collision catches small targets even when a missile crosses them in one frame.
function segmentImpact(x,y,nx,ny,entity,radius){const dx=nx-x,dy=ny-y,ox=x-entity.x,oy=y-entity.y,c=ox*ox+oy*oy-radius*radius;if(c<=0)return 0;const a=dx*dx+dy*dy;if(a===0)return null;const b=2*(ox*dx+oy*dy),disc=b*b-4*a*c;if(disc<0)return null;const t=(-b-Math.sqrt(disc))/(2*a);return t>=0&&t<=1?t:null}
function updateMissile(dt){if(state!=='play'||paused)return;if(missile&&stepMissile(missile,dt)){missile=null;updateMissileHud()}if(wingMissiles.length){wingMissiles=wingMissiles.filter(m=>!stepMissile(m,dt));if(!wingMissiles.length)updateMissileHud()}}
function stepMissile(m,dt){m.life-=dt;if(m.life<=0){burst(m.x,m.y,'#ffce83',8);return true}if(m.target&&m.target.hp<=0)m.target=null;if(m.target){const desired=Math.atan2(m.target.y-m.y,m.target.x-m.x),delta=Math.atan2(Math.sin(desired-m.angle),Math.cos(desired-m.angle));m.angle+=Math.max(-3.8*dt,Math.min(3.8*dt,delta))}m.speed=Math.min(480,m.speed+120*dt);const nx=m.x+Math.cos(m.angle)*m.speed*dt,ny=m.y+Math.sin(m.angle)*m.speed*dt;let impact=null,best=Infinity;for(const [group,factor] of [[fragments,1],[enemies,1],[rocks,.72],[wrecks,.62],[monsters,.65]])for(const e of group){if(e.hp<=0||e.life<=0)continue;const t=segmentImpact(m.x,m.y,nx,ny,e,e.r*factor+m.r);if(t!==null&&t<best){best=t;impact=e}}if(impact){m.x+=(nx-m.x)*best;m.y+=(ny-m.y)*best;if(fragments.includes(impact))dissolveFragment(impact);else destroyableHit(impact,6,'#ffbc69',28);burst(m.x,m.y,'#ffe3a3',24);sfx('boom');return true}m.x=nx;m.y=ny;const life=.3;particles.push({x:m.x-Math.cos(m.angle)*12,y:m.y-Math.sin(m.angle)*12,vx:-Math.cos(m.angle)*35,vy:-Math.sin(m.angle)*35,life,max:life,color:'#ffc47a',r:2,soft:true});return false}
function drawMissile(){if(missile)drawOneMissile(missile);for(const m of wingMissiles)drawOneMissile(m)}
function drawOneMissile(missile){ctx.save();ctx.translate(missile.x,missile.y);ctx.rotate(missile.angle);ctx.fillStyle='#ffe4b5';ctx.strokeStyle='#ffab56';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(12,0);ctx.lineTo(-8,-4);ctx.lineTo(-6,0);ctx.lineTo(-8,4);ctx.closePath();ctx.fill();ctx.stroke();drawPlume(-8,0,-1,0,28,3,'#ff5268');ctx.restore()}
function drawTargetLock(){if(state!=='play'||!lockTarget||lockTarget.hp<=0)return;const t=lockTarget,p=lockProgress,smooth=p*p*(3-2*p),x=player.x+(t.x-player.x)*smooth,y=player.y+(t.y-player.y)*smooth,r=t.r+15+(1-p)*15;ctx.save();ctx.strokeStyle=p>=1?'#ffb567':'#8ce9ec';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=1.5;ctx.globalAlpha=.85;ctx.beginPath();for(const sx of [-1,1])for(const sy of [-1,1]){ctx.moveTo(x+sx*r,y+sy*(r-10));ctx.lineTo(x+sx*r,y+sy*r);ctx.lineTo(x+sx*(r-10),y+sy*r)}ctx.stroke();ctx.beginPath();ctx.arc(x,y,r+6,-Math.PI/2,-Math.PI/2+p*Math.PI*2);ctx.stroke();ctx.font='10px "Chakra Petch",sans-serif';ctx.textAlign='center';ctx.fillText(p>=1?'AGGANCIATO':'AGGANCIO',x,y-r-14);ctx.restore()}
addEventListener('auxclick',e=>{if(e.button===1&&state==='play')e.preventDefault()});

function beltCorridor(){const points=[];for(let i=0;i<=60;i++){const t=i/60,r=world.r+140+t*1040,a=approachAngle+Math.PI+Math.sin(t*Math.PI*2)*.48;points.push({x:world.x+Math.cos(a)*r,y:world.y+Math.sin(a)*r})}return points}
function pointSegmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)}
function makeOrbitalBelt(){const path=beltCorridor(),inner=world.r+220,outer=world.r+950,materials=[{fill:'#584435',edge:'#d7ac78',hp:3,explosive:1},{fill:'#294e56',edge:'#87d4cf',hp:7,explosive:1.6},{fill:'#503756',edge:'#d3a0ee',hp:12,explosive:2.4}];let placed=0;for(let attempt=0;attempt<24000&&placed<300;attempt++){const a=Math.random()*Math.PI*2,d=Math.sqrt(inner*inner+Math.random()*(outer*outer-inner*inner)),r=48+Math.random()*20,candidate={x:world.x+Math.cos(a)*d,y:world.y+Math.sin(a)*d};if(path.some((p,i)=>i&&pointSegmentDistance(candidate,path[i-1],p)<r*.72+38))continue;if(rocks.some(o=>o.orbital&&Math.hypot(candidate.x-o.x,candidate.y-o.y)<(r+o.r)*.72+10))continue;const material=materials[placed%3];rocks.push({rock:true,orbital:true,...candidate,r,vx:0,vy:0,rot:Math.random()*6.28,spin:0,...material,hit:0});placed++}}
function updateApproach(){const d=Math.hypot(world.x-player.x,world.y-player.y),progress=1-d/(world.dist||world.x),thresholds=[.25,.48,.68,.84];while(reinforcementStage<thresholds.length&&progress>=thresholds[reinforcementStage]){reinforcementStage++;const count=2+reinforcementStage+Math.floor(world.p.difficulty/2);for(let i=0;i<count;i++){const a=Math.atan2(world.y-player.y,world.x-player.x)+(i-(count-1)/2)*.3;spawnEnemy(player.x+Math.cos(a)*(650+i*35),player.y+Math.sin(a)*(650+i*35))}status('RINFORZI NEMICI · ONDATA '+reinforcementStage,2200)}if(!fleetWarned&&d<world.r+2600){fleetWarned=true;const n=enemies.filter(e=>e.guard&&e.hp>0).length;if(n)status('FLOTTA NEMICA IN ATTESA ATTORNO A '+world.p.name+' · '+n+' NAVI',3200)}if(!beltWarned&&d<world.r+1300){beltWarned=true;status('CINTURA ROCCIOSA · CERCA I PASSAGGI · ATTENZIONE AI FRAMMENTI',4500)}}

function spawnMeteor(){const a=Math.random()*Math.PI*2,d=Math.hypot(W,H)/2+350,x=player.x+Math.cos(a)*d,y=player.y+Math.sin(a)*d,angle=Math.atan2(player.y-y,player.x-x);meteor={x,y,angle,vx:Math.cos(angle)*1250,vy:Math.sin(angle)*1250,r:24,life:d/1250+4,warning:3,hitPlayer:false,hp:4,maxHp:4};updateMeteorAlert();status('ALLARME · METEORITE IN ARRIVO · SCHIVA',4000);tone(240,.3,'square',.025,120)}
function updateMeteor(dt){if(state!=='play'||paused)return;updateMeteorAlert();if(!meteor){if(nearAtmosphere()&&meteorTimer>8)meteorTimer=2+Math.random()*3;meteorTimer-=dt;if(meteorTimer<=0)spawnMeteor();return}const m=meteor;if(m.warning>0){const previous=Math.ceil(m.warning);m.warning=Math.max(0,m.warning-dt);if(Math.ceil(m.warning)<previous)tone(380,.12,'square',.025,250);updateMeteorAlert();return}m.life-=dt;if(m.life<=0){meteor=null;meteorTimer=nextMeteorDelay();updateMeteorAlert();return}const nx=m.x+m.vx*dt,ny=m.y+m.vy*dt;const impacts=[];for(const [group,factor] of [[enemies,1],[rocks,.72],[wrecks,.62],[monsters,.65]])for(const e of group){if(e.hp<=0)continue;const t=segmentImpact(m.x,m.y,nx,ny,e,e.r*factor+m.r);if(t!==null)impacts.push({e,t})}if(!m.hitPlayer){const t=segmentImpact(m.x,m.y,nx,ny,player,player.r+m.r);if(t!==null)impacts.push({e:player,t})}impacts.sort((a,b)=>a.t-b.t);for(const {e} of impacts){if(e===player){m.hitPlayer=true;damage(75,true);status('IMPATTO METEORITE · SCAFO −75%',1800)}else destroyableHit(e,e.hp,'#ffad59',28);if(state!=='play')return}for(const b of bullets)if(b.life>0&&(segmentImpact(m.x,m.y,nx,ny,b,b.r+m.r)!==null||segmentImpact(b.px??b.x,b.py??b.y,b.x,b.y,m,b.r+m.r)!==null)){b.life=0;hitMeteor(1);if(!meteor)return;break}if(missile&&segmentImpact(m.x,m.y,nx,ny,missile,missile.r+m.r)!==null){missile=null;updateMissileHud();hitMeteor(6);if(!meteor)return}pickups=pickups.filter(p=>segmentImpact(m.x,m.y,nx,ny,p,p.r+m.r)===null);m.x=nx;m.y=ny;particles.push({x:m.x,y:m.y,vx:-m.vx*.12,vy:-m.vy*.12,life:.4,max:.4,color:'#ff9d45',r:8,soft:true})}
function drawMeteor(){if(!meteor)return;const m=meteor;if(m.warning>0){const distance=Math.min(W,H)*.33,x=player.x-Math.cos(m.angle)*distance,y=player.y-Math.sin(m.angle)*distance;ctx.save();ctx.strokeStyle='#ff9d45';ctx.fillStyle='#ffbf80';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,30,0,Math.PI*2);ctx.moveTo(x,y-15);ctx.lineTo(x,y+6);ctx.stroke();ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText('!',x,y+19);ctx.fillText('METEORITE · '+Math.ceil(m.warning)+' s',x,y-42);ctx.restore();return}ctx.save();ctx.translate(m.x,m.y);ctx.rotate(m.angle);ctx.globalCompositeOperation='screen';const glow=ctx.createRadialGradient(-20,0,4,-20,0,95);glow.addColorStop(0,'rgba(255,196,100,.38)');glow.addColorStop(1,'rgba(255,75,10,0)');ctx.fillStyle=glow;ctx.fillRect(-115,-95,190,190);for(let i=0;i<5;i++){const length=190-i*22,width=22-i*3,tail=ctx.createLinearGradient(-length,0,10,0);tail.addColorStop(0,'rgba(255,65,15,0)');tail.addColorStop(.65,`rgba(255,105,28,${.1+i*.035})`);tail.addColorStop(1,'rgba(255,235,177,.8)');ctx.fillStyle=tail;ctx.beginPath();ctx.moveTo(10,-width);ctx.quadraticCurveTo(-length*.35,-width*.9,-length,Math.sin(m.life*12+i)*5);ctx.quadraticCurveTo(-length*.35,width*.8,10,width);ctx.closePath();ctx.fill()}ctx.restore();if(!m.core)m.core={r:m.r,rot:m.angle,fill:'#665042',edge:'#ffc78d'};Object.assign(m.core,{x:m.x,y:m.y,rot:m.angle+m.life*.8,hp:m.hp??4,maxHp:m.maxHp??4});drawRock(m.core);ctx.save();ctx.translate(m.x,m.y);ctx.rotate(m.angle);ctx.shadowBlur=14;ctx.shadowColor='#ff982f';ctx.strokeStyle='#ffe0a1';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,m.r*.82,-1.1,1.1);ctx.stroke();ctx.restore()}

// Perspective star streaks accelerate into a blue tunnel, then collapse at arrival.
function drawHyperspace(t){const cx=W/2,cy=H/2,scale=Math.hypot(W,H)*.62,charge=Math.min(1,t/.75),cruise=Math.max(0,Math.min(1,(t-.7)/.45)),exit=Math.max(0,Math.min(1,(t-3.05)/.55)),reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;ctx.save();ctx.fillStyle='#01040d';ctx.fillRect(0,0,W,H);const fog=ctx.createRadialGradient(cx,cy,10,cx,cy,scale);fog.addColorStop(0,'#020716');fog.addColorStop(.18,`rgba(22,78,150,${.2+cruise*.3})`);fog.addColorStop(.55,`rgba(24,102,181,${cruise*.3})`);fog.addColorStop(1,'#01030b');ctx.fillStyle=fog;ctx.fillRect(0,0,W,H);if(!reduced){ctx.globalCompositeOperation='screen';for(const star of warpStars){const travel=t*.04+Math.max(0,t-.55)**1.6*.26,z=1-((star.depth+travel)%1),depth=.12+z*1.7,r=star.radius*scale*.14/depth,stretch=(2+charge**4*90+cruise*170)*(1-exit*.85),length=Math.min(scale*.7,stretch/(depth*depth)),ca=Math.cos(star.angle),sa=Math.sin(star.angle),x=cx+ca*r,y=cy+sa*r,tx=cx+ca*(r+length),ty=cy+sa*(r+length);if(r>scale*1.5)continue;const streak=ctx.createLinearGradient(x,y,tx,ty);streak.addColorStop(0,'rgba(86,164,255,0)');streak.addColorStop(.45,`rgba(108,194,255,${.22+cruise*.3})`);streak.addColorStop(1,`rgba(229,247,255,${.45+cruise*.5})`);ctx.strokeStyle=streak;ctx.lineWidth=star.width*(.5+cruise*.65)/Math.max(.6,depth);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(tx,ty);ctx.stroke()}ctx.globalCompositeOperation='source-over'}const entryFlash=Math.max(0,1-Math.abs(t-.84)/.13)*.7,arrivalFlash=exit*exit;ctx.fillStyle=`rgba(210,237,255,${reduced?arrivalFlash*.2:Math.max(entryFlash,arrivalFlash)})`;ctx.fillRect(0,0,W,H);ctx.restore();$('warpPhase').textContent=t<.75?'CALCOLO DEL SALTO':t<3.05?'IPERSPAZIO':'USCITA DALL’IPERSPAZIO';$('warpDestination').textContent='ROTTA BLOCCATA / '+planets[selected].name}

function updateMeteorAlert(){const warning=!!meteor&&meteor.warning>0;show('meteorAlert',warning);if(warning)$('meteorAlert').textContent='⚠ METEORITE IN ARRIVO · '+Math.ceil(meteor.warning)+' s · CAMBIA ROTTA'}

// Resolve thrust independently along the bow and sideways: boosted forward speed
// must never block the lateral engines or reverse thrust.
// Thrust follows screen directions (up = up), independent of where the bow points.
function applyShipThrust(ix,iy,boost,dt){const length=Math.hypot(ix,iy);if(!length)return;const sp=1+.12*upg('speed'),dx=ix/length,dy=iy/length,limit=(boost?590:240)*sp,accel=(boost?560:430)*sp;let along=player.vx*dx+player.vy*dy,px=player.vx-along*dx,py=player.vy-along*dy;if(along<limit)along=Math.min(limit,along+accel*dt*(along<0?1.7:1));const grip=Math.exp(-1.6*dt);px*=grip;py*=grip;player.vx=along*dx+px;player.vy=along*dy+py}
// Converts a screen-space thrust into the ship's local engines, so the right nozzles light up.
function worldToShipThrust(x,y){const length=Math.hypot(x,y);if(!length)return{forward:0,strafe:0};const ca=Math.cos(player.angle),sa=Math.sin(player.angle),f=(x*ca+y*sa)/length,l=(-x*sa+y*ca)/length;return{forward:f>.35?1:f<-.35?-1:0,strafe:l>.35?1:l<-.35?-1:0}}

function spawnFragments(source,count=8){for(let i=0;i<count;i++){const a=i/count*Math.PI*2+Math.random()*.3,speed=(140+Math.random()*180)*(source.explosive||1);fragments.push({x:source.x+Math.cos(a)*(source.r||20)*.4,y:source.y+Math.sin(a)*(source.r||20)*.4,vx:Math.cos(a)*speed+(source.vx||0)*.12,vy:Math.sin(a)*speed+(source.vy||0)*.12,r:5+Math.random()*6,rot:a,spin:(Math.random()-.5)*5,life:7,cooldown:0})}if(fragments.length>160)fragments.splice(0,fragments.length-160)}
function shatterMeteor(){if(!meteor)return;if(Math.random()<SHIELD_DROP_CHANCE)dropShieldPill(meteor.x,meteor.y);spawnFragments(meteor,14);burst(meteor.x,meteor.y,'#ffd099',28);sfx('boom');meteor=null;meteorTimer=nextMeteorDelay();updateMeteorAlert();status('METEORITE FRAMMENTATO · SCHIVA I DETRITI',2200)}
function reflectFragment(f,e,radius){let dx=f.x-e.x,dy=f.y-e.y,d=Math.hypot(dx,dy);if(d<.001){dx=1;dy=0;d=1}const nx=dx/d,ny=dy/d,along=f.vx*nx+f.vy*ny;f.x=e.x+nx*(radius+f.r+1);f.y=e.y+ny*(radius+f.r+1);if(along<0){f.vx-=2*along*nx;f.vy-=2*along*ny}}
function updateFragments(dt){if(state!=='play'||paused)return;for(const f of fragments){f.life-=dt;f.cooldown=Math.max(0,f.cooldown-dt);f.x+=f.vx*dt;f.y+=f.vy*dt;f.rot+=f.spin*dt;if(f.life<=0)continue;if(hit(f,player,f.r,player.r)){damage(9,false,true);reflectFragment(f,player,player.r);f.cooldown=.15}if(f.cooldown<=0){for(const e of [...rocks,...wrecks,...enemies,...monsters]){if(e.hp<=0)continue;const radius=e.r*(e.rock?.72:wrecks.includes(e)?.62:monsters.includes(e)?.65:1);if(hit(f,e,f.r,radius)){reflectFragment(f,e,radius);if(e.type)destroyableHit(e,1,'#ffad69',12);f.cooldown=.12;burst(f.x,f.y,'#e6bd84',2);break}}}}fragments=fragments.filter(f=>f.life>0)}
function drawFragment(f){ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.rot);ctx.fillStyle='#725342';ctx.strokeStyle='#ffbf7e';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(f.r,0);ctx.lineTo(0,-f.r*.7);ctx.lineTo(-f.r,f.r*.2);ctx.lineTo(0,f.r);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}

function enemyImpact(e){if(e.hp<=0||(e.impactCooldown||0)>0)return;e.impactCooldown=.5;destroyableHit(e,1,'#ff8a65',16)}
function resolveEnemyObstacle(e,o,radius,swept=true){const combined=e.r+radius,px=e.prevX??e.x,py=e.prevY??e.y;let dx=e.x-o.x,dy=e.y-o.y,d=Math.hypot(dx,dy),contact=d<combined;if(swept&&!contact){const t=segmentImpact(px,py,e.x,e.y,o,combined);if(t!==null&&t>0){e.x=px+(e.x-px)*t;e.y=py+(e.y-py)*t;dx=e.x-o.x;dy=e.y-o.y;d=Math.hypot(dx,dy);contact=true}}if(!contact)return;if(d<.001){dx=px-o.x;dy=py-o.y;d=Math.hypot(dx,dy);if(d<.001){dx=1;dy=0;d=1}}const nx=dx/d,ny=dy/d,closing=(e.vx-(o.vx||0))*nx+(e.vy-(o.vy||0))*ny;e.x=o.x+nx*(combined+.5);e.y=o.y+ny*(combined+.5);if(closing<0){e.vx-=nx*closing*1.45;e.vy-=ny*closing*1.45}enemyImpact(e)}
function updateEnemyCollisions(dt){const obstacles=[...rocks.filter(r=>r.hp>0).map(e=>[e,e.r*.72]),...wrecks.filter(e=>e.hp>0).map(e=>[e,e.r*.62]),...monsters.filter(e=>e.hp>0).map(e=>[e,e.r*.65]),[world,world.r]];for(const e of enemies){e.impactCooldown=Math.max(0,(e.impactCooldown||0)-dt);if(e.hp<=0)continue;for(const [o,r] of obstacles){if(e.hp<=0)break;resolveEnemyObstacle(e,o,r)}}for(let i=0;i<enemies.length;i++)for(let j=i+1;j<enemies.length;j++){const a=enemies[i],b=enemies[j];if(a.hp<=0||b.hp<=0||!hit(a,b,a.r,b.r))continue;let dx=a.x-b.x,dy=a.y-b.y,d=Math.hypot(dx,dy);if(d<.001){dx=1;dy=0;d=1}const nx=dx/d,ny=dy/d,separation=(a.r+b.r-d+.5)/2;a.x+=nx*separation;a.y+=ny*separation;b.x-=nx*separation;b.y-=ny*separation;const closing=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;if(closing<0){a.vx-=nx*closing*.7;a.vy-=ny*closing*.7;b.vx+=nx*closing*.7;b.vy+=ny*closing*.7}}for(const e of enemies)if(e.hp>0)for(const [o,r] of obstacles)resolveEnemyObstacle(e,o,r,false)}

function resolveBulletImpacts(){for(const b of bullets){if(b.life<=0)continue;const candidates=[...fragments.filter(f=>f.life>0).map(f=>[f,f.r,'#d8e6f2']),...rocks.filter(e=>e.hp>0).map(e=>[e,e.r*.72,'#b1bac2']),...wrecks.filter(e=>e.hp>0).map(e=>[e,e.r*.62,'#8194a7']),...monsters.filter(e=>e.hp>0).map(e=>[e,e.r*.65,'#a9ff78']),...(b.friendly?enemies.filter(e=>e.hp>0):[]).map(e=>[e,e.r,'#ff5a3d'])];if(!b.friendly)candidates.push([player,player.r,'#ff5a3d']);let closest=null,time=Infinity;for(const [e,r,color] of candidates){const t=segmentImpact(b.px??b.x,b.py??b.y,b.x,b.y,e,r+b.r);if(t!==null&&t<time){time=t;closest={e,color}}}if(closest){b.life=0;const {e,color}=closest;if(fragments.includes(e))dissolveFragment(e);else if(e===player)damage(10);else{enemyFire=!b.friendly;destroyableHit(e,b.dmg||1,color,22);enemyFire=false}}}}
function dropWreckSalvage(w){for(let i=0;i<4;i++){const a=i*Math.PI/2;pickups.push({x:w.x+Math.cos(a)*25,y:w.y+Math.sin(a)*25,kind:'energy',life:40,r:12})}status('RELITTO DISTRUTTO · 4 RIFORNIMENTI ENERGETICI',2200)}
function createShockwave(x,y,power=1){const radius=230*Math.sqrt(power);shockwaves.push({x,y,life:.55,max:.55,radius});if(shockwaves.length>40)shockwaves.shift();const objects=[player,...enemies,...rocks,...wrecks,...monsters,...fragments,...pickups];for(const o of objects){if(!o||o.hp<=0)continue;const dx=o.x-x,dy=o.y-y,d=Math.hypot(dx,dy);if(d<1||d>radius)continue;const mass=o.orbital?.12:wrecks.includes(o)?.2:1,impulse=(1-d/radius)*48*mass*power;o.vx=(o.vx||0)+dx/d*impulse;o.vy=(o.vy||0)+dy/d*impulse}}
function updateShockwaves(dt){for(const m of monsters){m.x+=(m.vx||0)*dt;m.y+=(m.vy||0)*dt;m.vx=(m.vx||0)*Math.exp(-3*dt);m.vy=(m.vy||0)*Math.exp(-3*dt)}shockwaves.forEach(w=>w.life-=dt);shockwaves=shockwaves.filter(w=>w.life>0);for(const p of pickups){p.x+=(p.vx||0)*dt;p.y+=(p.vy||0)*dt;p.vx=(p.vx||0)*Math.exp(-3*dt);p.vy=(p.vy||0)*Math.exp(-3*dt)}for(const r of rocks)if(r.orbital){r.vx*=Math.exp(-3*dt);r.vy*=Math.exp(-3*dt)}}
function drawShockwaves(){for(const w of shockwaves){const progress=1-w.life/w.max;ctx.save();ctx.strokeStyle=`rgba(192,224,255,${(1-progress)*.35})`;ctx.lineWidth=1+(1-progress)*2;ctx.beginPath();ctx.arc(w.x,w.y,10+progress*((w.radius||230)-10),0,Math.PI*2);ctx.stroke();ctx.restore()}}

function enemySpawnPosition(x,y,r,offscreen=false){if(!world)return{x,y};const outer=world.r+1150,angle=Math.atan2(y-world.y,x-world.x);if(Math.hypot(x-world.x,y-world.y)<outer){x=world.x+Math.cos(angle)*outer;y=world.y+Math.sin(angle)*outer}for(let i=0;i<150;i++){const outsideView=!offscreen||Math.abs(x-player.x)>W/2+r+100||Math.abs(y-player.y)>H/2+r+100,outsideBelt=Math.hypot(x-world.x,y-world.y)>=outer-1e-6;if(outsideView&&outsideBelt&&![...rocks,...wrecks,...monsters].some(o=>o.hp>0&&Math.hypot(x-o.x,y-o.y)<o.r+r+25)&&!enemies.some(o=>o.hp>0&&Math.hypot(x-o.x,y-o.y)<o.r+r+10))return{x,y};const a=angle+i*.27;if(offscreen){const d=Math.hypot(W,H)*.65+200+i*7;x=player.x+Math.cos(a)*d;y=player.y+Math.sin(a)*d}else{const d=outer+Math.floor(i/20)*100;x=world.x+Math.cos(a)*d;y=world.y+Math.sin(a)*d}}return{x:player.x+Math.hypot(W,H)+Math.hypot(player.x-world.x,player.y-world.y)+outer+500,y:player.y}}
function avoidEnemyObstacles(e,tx,ty){const speed=Math.hypot(tx,ty);if(speed<1)return{x:tx,y:ty};const desired=Math.atan2(ty,tx),look=110+Math.hypot(e.vx,e.vy)*.65,obstacles=[...rocks.filter(o=>o.hp>0).map(o=>[o,o.r*.72]),...wrecks.filter(o=>o.hp>0).map(o=>[o,o.r*.62]),...monsters.filter(o=>o.hp>0).map(o=>[o,o.r*.65]),...enemies.filter(o=>o!==e&&o.hp>0).map(o=>[o,o.r]),[world,world.r]].filter(([o,r])=>Math.hypot(o.x-e.x,o.y-e.y)<look+r+e.r+35);let best=null;for(let i=0;i<17;i++){const offset=i===0?0:Math.ceil(i/2)*(i%2?1:-1)*Math.PI/8,a=desired+offset,nx=e.x+Math.cos(a)*look,ny=e.y+Math.sin(a)*look;let clearance=1;for(const [o,r] of obstacles){const t=segmentImpact(e.x,e.y,nx,ny,o,r+e.r+12);if(t!==null)clearance=Math.min(clearance,t)}const score=Math.cos(offset)*1.3+clearance*3-(clearance<1?4:0);if(!best||score>best.score)best={a,score,clearance}}const factor=best.clearance<1?Math.max(.08,best.clearance*.35):1;return{x:Math.cos(best.a)*speed*factor,y:Math.sin(best.a)*speed*factor}}

