function initBarrierPlasma(){const a=audioCtx;plasmaGain=a.createGain();plasmaGain.gain.value=0;plasmaGain.connect(audioBus);plasmaTone=a.createOscillator();plasmaTone.type='sine';plasmaTone.frequency.value=172;plasmaTone.connect(plasmaGain);plasmaTone.start();const harmonic=a.createOscillator(),harmonicGain=a.createGain();harmonic.type='triangle';harmonic.frequency.value=179;harmonicGain.gain.value=.23;harmonic.connect(harmonicGain);harmonicGain.connect(plasmaGain);harmonic.start();const wobble=a.createOscillator(),depth=a.createGain();wobble.frequency.value=6;depth.gain.value=9;wobble.connect(depth);depth.connect(plasmaTone.frequency);wobble.start();const buffer=a.createBuffer(1,a.sampleRate,a.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const source=a.createBufferSource(),noiseLevel=a.createGain();source.buffer=buffer;source.loop=true;noiseLevel.gain.value=.4;plasmaFilter=a.createBiquadFilter();plasmaFilter.type='bandpass';plasmaFilter.frequency.value=780;source.connect(plasmaFilter);plasmaFilter.connect(noiseLevel);noiseLevel.connect(plasmaGain);source.start()}

