 const c=Math.cos(player.angle),s=Math.sin(player.angle),bx=player.vx*.45,by=player.vy*.45;shipDebris=[];
 for(const piece of SHIP_PIECES){let cx=0,cy=0;piece.pts.forEach(([x,y])=>{cx+=x;cy+=y});cx/=piece.pts.length;cy/=piece.pts.length;const wx=cx*c-cy*s,wy=cx*s+cy*c,len=Math.hypot(wx,wy)||1,dir=Math.atan2(wy,wx)+(Math.random()-.5)*.6,speed=90+Math.random()*170;
  shipDebris.push({x:player.x+wx,y:player.y+wy,vx:bx+Math.cos(dir)*speed,vy:by+Math.sin(dir)*speed,angle:player.angle,spin:(Math.random()<.5?-1:1)*(2+Math.random()*6),pts:piece.pts.map(([x,y])=>[x-cx,y-cy]),color:piece.color,glass:!!piece.glass,engine:!!piece.engine,heat:1,burn:1.2+Math.random()*1.6,emit:0})}
 for(let i=0;i<34;i++){const a=Math.random()*6.28,sp=180+Math.random()*380,z=1.2+Math.random()*3;shipDebris.push({x:player.x,y:player.y,vx:bx+Math.cos(a)*sp,vy:by+Math.sin(a)*sp,angle:Math.random()*6.28,spin:(Math.random()-.5)*22,pts:[[z,0],[-z*.7,-z*.8],[-z*.4,z*.9]],color:Math.random()<.5?'#9fb4c0':'#e8f7fa',shard:true,heat:Math.random(),burn:Math.random()<.35?.5+Math.random():0,emit:0})}
