 for(const d of shipDebris){d.x+=d.vx*dt;d.y+=d.vy*dt;const drag=Math.exp(-(d.shard?.9:.35)*dt);d.vx*=drag;d.vy*=drag;d.angle+=d.spin*dt;d.spin*=Math.exp(-.25*dt);d.heat=Math.max(0,d.heat-dt*(d.shard?1.2:.4));if(d.burn>0){d.burn-=dt;d.emit-=dt;if(d.emit<=0){d.emit=d.shard?.05:.025;particles.push({x:d.x,y:d.y,vx:d.vx*.2+(Math.random()-.5)*30,vy:d.vy*.2+(Math.random()-.5)*30,life:.25+Math.random()*.35,max:.6,color:Math.random()<.5?'#ffb04a':'#ff6a2a',r:(d.shard?2:4)+Math.random()*4,soft:true});if(!d.shard&&Math.random()<.6)particles.push({x:d.x,y:d.y,vx:(Math.random()-.5)*24,vy:(Math.random()-.5)*24,life:1+Math.random(),max:2,color:'#47505b',r:4+Math.random()*5,smoke:true})}}}
 bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt});bullets=bullets.filter(b=>b.life>0);
 for(const e of enemies){e.x+=(e.vx||0)*dt;e.y+=(e.vy||0)*dt;e.vx=(e.vx||0)*Math.exp(-1.5*dt);e.vy=(e.vy||0)*Math.exp(-1.5*dt)}
