function spawnGuardFleet(){
 const d=world.p.difficulty,count=8+d*3,groups=Math.ceil(count/4);let left=count;
 for(let g=0;g<groups;g++){
  const front=g<Math.ceil(groups/2),a=front?approachAngle+Math.PI+(g-(Math.ceil(groups/2)-1)/2)*.55+(Math.random()-.5)*.2:Math.random()*Math.PI*2,r=world.r+1300+Math.random()*250,cx=world.x+Math.cos(a)*r,cy=world.y+Math.sin(a)*r,n=Math.min(left,4),dir=Math.random()<.5?-1:1;
  for(let i=0;i<n;i++){
   const ox=[0,-95,95,0][i],oy=[0,-80,-80,-160][i],ta=a+Math.PI/2;
   spawnEnemy(cx+Math.cos(ta)*ox+Math.cos(a)*oy,cy+Math.sin(ta)*ox+Math.sin(a)*oy,false);
   const e=enemies[enemies.length-1];e.guard=true;e.orbitDir=dir;
  }
  left-=n;
 }
}
// Le guardie pattugliano lentamente in orbita; se una vede il giocatore avvisa la sua squadriglia.
function guardPatrol(e,dt){
 const dx=e.x-world.x,dy=e.y-world.y,r=Math.max(1,Math.hypot(dx,dy)),tx=-dy/r*e.orbitDir*32,ty=dx/r*e.orbitDir*32;
 e.vx+=(tx-e.vx)*Math.min(1,dt*2);e.vy+=(ty-e.vy)*Math.min(1,dt*2);e.angle=Math.atan2(e.vy,e.vx);
 for(const o of enemies)if(o!==e&&o.alerted&&o.hp>0&&o.guard&&Math.hypot(o.x-e.x,o.y-e.y)<520){e.alerted=true;break}
}
function updateMeteorShower(dt){
 if(state!=='play'||paused||arrivalRemaining>0)return;
 if(nearAtmosphere()){
  if(!showerWarned){showerWarned=true;status('INGRESSO NELL’ATMOSFERA · PIOGGIA DI METEORITI',3200);tone(200,.4,'sawtooth',.02,90)}
  showerTimer-=dt;
  if(showerTimer<=0){spawnShowerMeteor();const d=world.p.difficulty;showerTimer=Math.max(.35,1.15-d*.14)*(.6+Math.random()*.8)}
 }
 for(const m of shower){
  if(m.warning>0){m.warning-=dt;continue}
  m.life-=dt;const nx=m.x+m.vx*dt,ny=m.y+m.vy*dt;
  if(!m.hitPlayer&&segmentImpact(m.x,m.y,nx,ny,player,player.r+m.r)!==null){m.hitPlayer=true;m.life=0;damage(16);burst(nx,ny,'#ffb36b',14);status('IMPATTO METEORITE · SCAFO −16%',1200);if(state!=='play')return;continue}
  for(const e of enemies)if(e.hp>0&&segmentImpact(m.x,m.y,nx,ny,e,e.r+m.r)!==null){destroyableHit(e,2,'#ffad59',12);m.life=0;break}
  if(m.life<=0)continue;
  for(const o of rocks)if(o.hp>0&&segmentImpact(m.x,m.y,nx,ny,o,o.r*.72+m.r)!==null){m.life=0;burst(nx,ny,'#ffc07a',10);break}
  if(m.life<=0)continue;
  for(const b of bullets)if(b.life>0&&segmentImpact(b.px??b.x,b.py??b.y,b.x,b.y,m,b.r+m.r+4)!==null){b.life=0;m.hp-=b.dmg||1;if(m.hp<=0){m.life=0;burst(m.x,m.y,'#ffd099',12);spawnFragments(m,4)}break}
  if(m.life<=0)continue;
  if(Math.hypot(nx-world.x,ny-world.y)<world.r*1.02){m.life=0;burst(nx,ny,'#ff8a3d',10);continue}
  m.x=nx;m.y=ny;
  particles.push({x:m.x,y:m.y,vx:-m.vx*.08,vy:-m.vy*.08,life:.3,max:.3,color:'#ff9d45',r:5,soft:true});
 }
 shower=shower.filter(m=>m.life>0);
}
// Meteoriti piccoli che cadono verso il pianeta passando vicino al giocatore.
function spawnShowerMeteor(){
 const toPlanet=Math.atan2(world.y-player.y,world.x-player.x),a=toPlanet+(Math.random()-.5)*1.3,speed=520+Math.random()*260,diag=Math.hypot(W,H)/2+120,side=(Math.random()-.5)*Math.max(W,H)*.9;
 const x=player.x-Math.cos(a)*diag-Math.sin(a)*side,y=player.y-Math.sin(a)*diag+Math.cos(a)*side,r=11+Math.random()*9;
 shower.push({x,y,angle:a,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r,life:diag*2/speed+1,warning:.45,hp:r>16?2:1,maxHp:r>16?2:1,hitPlayer:false,rot:Math.random()*6,fill:'#5d4638',edge:'#ffb87a'});
}
function drawMeteorShower(){
 for(const m of shower){
  if(m.warning>0){
   const dist=Math.min(W,H)*.42,x=player.x-Math.cos(m.angle)*dist,y=player.y-Math.sin(m.angle)*dist;
   ctx.save();ctx.globalAlpha=.35+.35*Math.sin(m.warning*30);ctx.strokeStyle='#ff9d45';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-Math.cos(m.angle-.5)*12,y-Math.sin(m.angle-.5)*12);ctx.lineTo(x,y);ctx.lineTo(x-Math.cos(m.angle+.5)*12,y-Math.sin(m.angle+.5)*12);ctx.stroke();ctx.restore();continue}
  ctx.save();ctx.translate(m.x,m.y);ctx.rotate(m.angle);ctx.globalCompositeOperation='screen';
  const len=60+m.r*4,tail=ctx.createLinearGradient(-len,0,6,0);tail.addColorStop(0,'rgba(255,70,20,0)');tail.addColorStop(.7,'rgba(255,120,40,.35)');tail.addColorStop(1,'rgba(255,230,170,.85)');
  ctx.fillStyle=tail;ctx.beginPath();ctx.moveTo(6,-m.r*.8);ctx.quadraticCurveTo(-len*.4,-m.r*.6,-len,0);ctx.quadraticCurveTo(-len*.4,m.r*.6,6,m.r*.8);ctx.closePath();ctx.fill();ctx.restore();
  m.rot+=.05;drawRock(m);
 }
}
